import{_ as a,y as o,a as s,o as r,a2 as n,D as i,g as h}from"./chunks/framework.DCcmcJcL.js";const k=JSON.parse('{"title":"Personalized Checkout Message","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/checkout-message.md","filePath":"generative-ai/checkout-message.md","lastUpdated":1789395222000}'),d={name:"generative-ai/checkout-message.md"};function g(c,e,l,p,u,m){const t=o("ImagePopup");return r(),s("div",null,[e[0]||(e[0]=n('<h1 id="personalized-checkout-message" tabindex="-1">Personalized Checkout Message <a class="header-anchor" href="#personalized-checkout-message" aria-label="Permalink to &quot;Personalized Checkout Message&quot;">​</a></h1><div class="feature-meta feature--ai"><span class="feature-meta__primary">Generative AI</span><span>Storefront</span></div><p>After an order is placed, the order confirmation page shows a standard thank-you line. With this feature on, Bagisto asks the model to write a short message for that order, mentioning what the shopper bought, and shows it under the thank-you heading in place of the standard line. It gives the moment a personal touch without any work on your side.</p><h2 id="turning-it-on" tabindex="-1">Turning it on <a class="header-anchor" href="#turning-it-on" aria-label="Permalink to &quot;Turning it on&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Magic AI &gt;&gt; Storefront Features</strong>. If your store has more than one channel, choose the channel at the top of the page.</li><li>In the <strong>Personalized Checkout Message</strong> section, switch <strong>Enabled</strong> on.</li><li>Choose the <strong>Model</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The Magic AI master switch and the provider key must be in place first; see <a href="./../configure/magic-ai.html">Generative AI Configuration</a>.</p><h2 id="what-the-shopper-sees" tabindex="-1">What the shopper sees <a class="header-anchor" href="#what-the-shopper-sees" aria-label="Permalink to &quot;What the shopper sees&quot;">​</a></h2><p>The message is written when the confirmation page opens, right after the order is placed. It is not stored with the order, so reloading the page asks the model again and the wording may differ. If the provider cannot be reached, the page shows its standard thank-you line and the order is unaffected.</p>',8)),i(t,{src:"/images/generative-ai/personalized-chckout-message.png",alt:"Personalized message on the order confirmation page"}),e[1]||(e[1]=h("p",null,"Because the text is generated for each order, wording varies from one order to the next. It draws only on the order itself, such as the items bought, and does not use anything the shopper has not shared with the store. Each confirmation page view is one request to the provider.",-1))])}const _=a(d,[["render",g]]);export{k as __pageData,_ as default};
